// @ts-nocheck
// Generated by paratha/build_studio.py from paratha/order.js
export function init(signal: AbortSignal) {
  const PL = window.PL;
  const $ = (s) => document.querySelector(s),
    $$ = (s) => [...document.querySelectorAll(s)];
  const MENU = {};
  $$(".dish").forEach(
    (d) => (MENU[d.dataset.id] = { name: d.dataset.name, price: +d.dataset.price }),
  );

  let cart = {},
    coupon = null;
  try {
    cart = JSON.parse(localStorage.getItem("pl_cart") || "{}");
  } catch (e) {}
  for (const id in cart) if (!MENU[id]) delete cart[id];
  const save = () => {
    try {
      localStorage.setItem("pl_cart", JSON.stringify(cart));
    } catch (e) {}
  };

  const lines = () =>
    Object.entries(cart)
      .filter(([, q]) => q > 0)
      .map(([id, q]) => ({ id, q, ...MENU[id], line: MENU[id].price * q }));
  function totals() {
    const sub = lines().reduce((s, l) => s + l.line, 0);
    let disc = 0,
      msg = "";
    if (coupon) {
      if (sub < coupon.min)
        msg = `${coupon.code} needs a subtotal of ${PL.money(coupon.min)} or more.`;
      else
        disc =
          coupon.type === "percent"
            ? Math.round(sub * coupon.value) / 100
            : Math.min(coupon.value, sub);
    }
    const gst = Math.round((sub - disc) * PL.gst * 100) / 100;
    return { sub, disc, gst, tot: sub - disc + gst, msg, n: lines().reduce((s, l) => s + l.q, 0) };
  }

  const drawer = $("#cart"),
    scrim = $("#scrim");
  const open = () => {
    drawer.inert = false;
    drawer.classList.add("open");
    scrim.classList.add("open");
    drawer.setAttribute("aria-hidden", "false");
    setTimeout(() => $("#cart .x").focus(), 50);
  };
  const close = () => {
    drawer.classList.remove("open");
    scrim.classList.remove("open");
    drawer.setAttribute("aria-hidden", "true");
    drawer.inert = true;
  };
  $$("[data-cart-open]").forEach((b) => b.addEventListener("click", open));
  $$("[data-cart-close]").forEach((b) => b.addEventListener("click", close));
  scrim.addEventListener("click", close);
  addEventListener(
    "keydown",
    (e) => {
      if (e.key === "Escape") close();
    },
    { signal },
  );

  function render() {
    const L = lines(),
      T = totals();
    $$(".js-count").forEach((e) => (e.textContent = T.n));
    $$(".js-total").forEach((e) => (e.textContent = PL.money(T.tot)));
    document.body.classList.toggle("has-cart", T.n > 0);
    $$(".dish").forEach((d) => {
      const q = cart[d.dataset.id] || 0;
      d.classList.toggle("in-cart", q > 0);
      d.querySelector(".q").textContent = q ? q : "";
    });
    $("#cart-items").innerHTML = L.length
      ? L.map(
          (l) => `
      <li><div><b>${l.name}</b><span>${PL.money(l.price)} each</span></div>
        <div class="stepper" role="group" aria-label="Quantity of ${l.name}">
          <button type="button" data-dec="${l.id}" aria-label="One less ${l.name}">−</button><output>${l.q}</output><button type="button" data-inc="${l.id}" aria-label="One more ${l.name}">+</button>
        </div><strong>${PL.money(l.line)}</strong></li>`,
        ).join("")
      : `<li class="empty">Your order is empty. Add a paratha plate to get started.</li>`;
    $("#t-sub").textContent = PL.money(T.sub);
    $("#t-disc").textContent = T.disc ? "−" + PL.money(T.disc) : "—";
    $("#t-gst").textContent = PL.money(T.gst);
    $("#t-tot").textContent = PL.money(T.tot);
    $("#coupon-msg").textContent = coupon ? T.msg || `${coupon.code} applied: ${coupon.label}` : "";
    $("#coupon-msg").className = "cmsg " + (coupon && !T.msg ? "good" : coupon ? "bad" : "");
    $("#checkout").hidden = !L.length;
    save();
  }
  const add = (id, d = 1) => {
    cart[id] = Math.max(0, (cart[id] || 0) + d);
    if (!cart[id]) delete cart[id];
    render();
  };

  $$(".dish .add").forEach((b) =>
    b.addEventListener("click", () => {
      add(b.closest(".dish").dataset.id);
      b.classList.remove("bump");
      void b.offsetWidth;
      b.classList.add("bump");
      const live = $("#live");
      live.textContent = `${MENU[b.closest(".dish").dataset.id].name} added. ${totals().n} items in your order.`;
    }),
  );
  $("#cart-items").addEventListener("click", (e) => {
    const i = e.target.dataset.inc,
      d = e.target.dataset.dec;
    if (i) add(i, 1);
    if (d) add(d, -1);
  });

  $("#apply").addEventListener("click", () => {
    const code = $("#coupon").value.trim().toUpperCase();
    const c = PL.coupons.find((c) => c.code === code);
    coupon = c || null;
    render();
    if (!c && code) {
      $("#coupon-msg").textContent = `“${code}” isn't a valid code.`;
      $("#coupon-msg").className = "cmsg bad";
    }
  });
  $$("[data-code]").forEach((b) =>
    b.addEventListener("click", () => {
      $("#coupon").value = b.dataset.code;
      $("#apply").click();
      open();
    }),
  );

  /* tabs */
  $$(".tabs button").forEach((b) =>
    b.addEventListener("click", () => {
      const t = document.getElementById(b.dataset.target);
      if (!t) return;
      window.scrollTo({ top: t.getBoundingClientRect().top + scrollY - 150, behavior: "smooth" });
    }),
  );
  const tabObs = new IntersectionObserver(
    (es) =>
      es.forEach((e) => {
        if (e.isIntersecting)
          $$(".tabs button").forEach((b) =>
            b.setAttribute("aria-current", b.dataset.target === e.target.id ? "true" : "false"),
          );
      }),
    { rootMargin: "-40% 0px -55% 0px" },
  );
  $$(".cat").forEach((c) => tabObs.observe(c));

  /* checkout → GoHighLevel order webhook (Square payment is sent from GoHighLevel) */
  const when = $("#pickup"),
    timeWrap = $("#time-wrap");
  when.addEventListener("change", () => {
    timeWrap.hidden = when.value !== "later";
  });
  $("#checkout").addEventListener("submit", async (e) => {
    e.preventDefault();
    const f = e.target;
    if (!f.reportValidity()) return;
    const L = lines(),
      T = totals(),
      fd = new FormData(f);
    const pickup =
      fd.get("pickup") === "later" ? "Later today at " + fd.get("time") : "As soon as possible";
    const itemsText = L.map((l) => `${l.q} × ${l.name} (${PL.money(l.line)})`).join("\n");
    const data = {
      name: fd.get("name"),
      phone: fd.get("phone"),
      email: fd.get("email") || "",
      order_type: "Pickup",
      pickup_time: pickup,
      notes: fd.get("notes") || "",
      items: itemsText,
      item_count: String(T.n),
      subtotal: T.sub.toFixed(2),
      coupon: coupon && !T.msg ? coupon.code : "",
      discount: T.disc.toFixed(2),
      gst: T.gst.toFixed(2),
      total: T.tot.toFixed(2),
      order_json: JSON.stringify(
        L.map((l) => ({ id: l.id, name: l.name, qty: l.q, price: l.price })),
      ),
    };
    const btn = f.querySelector("[type=submit]");
    btn.disabled = true;
    btn.textContent = "Sending your order…";
    const sent = await PL.send("order", data);
    btn.disabled = false;
    btn.textContent = "Place pickup order";
    const summary = `Pickup order for ${data.name} (${data.phone})\n${itemsText}\n${data.coupon ? "Coupon: " + data.coupon + " (−" + PL.money(T.disc) + ")\n" : ""}Total incl. GST: ${PL.money(T.tot)}\nPickup: ${pickup}${data.notes ? "\nNotes: " + data.notes : ""}`;
    $("#order-summary").textContent = summary;
    $$("#order-ok [data-sent]").forEach((x) => (x.hidden = !sent));
    $$("#order-ok [data-fallback]").forEach((x) => (x.hidden = sent));
    $("#order-ok [data-sms]").href = PL.sms(summary);
    $("#order-ok").classList.add("show");
    f.hidden = true;
    $("#cart-body").hidden = true;
    if (sent) {
      cart = {};
      coupon = null;
      render();
      $("#checkout").hidden = true;
    }
  });
  $("#new-order").addEventListener("click", () => {
    $("#order-ok").classList.remove("show");
    $("#cart-body").hidden = false;
    $("#checkout").hidden = !lines().length;
  });
  render();
}
